package com.citacloud.app.views;
import com.citacloud.app.models.*; import com.citacloud.app.security.*; import com.citacloud.app.services.*; import com.vaadin.flow.component.button.*; import com.vaadin.flow.component.combobox.ComboBox; import com.vaadin.flow.component.grid.Grid; import com.vaadin.flow.component.html.*; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.component.textfield.BigDecimalField; import com.vaadin.flow.component.textfield.TextField; import com.vaadin.flow.component.dialog.Dialog; import com.vaadin.flow.router.*; import jakarta.annotation.security.PermitAll; import java.math.BigDecimal; import java.util.*;
@Route(value="facturacion",layout=MainLayout.class) @PageTitle("Facturación | CitaCloud") @PermitAll public class FacturacionView extends VerticalLayout {final FacturacionService service;final PacienteService pacientes;final UUID empresa;final Grid<Factura> grid=new Grid<>(Factura.class,false);
 public FacturacionView(FacturacionService s,PacienteService p){service=s;pacientes=p;TenantUserDetails u=AuthService.getAuthenticatedUser();empresa=u==null?null:u.getEmpresaId();setSizeFull();setPadding(true);Button nueva=new Button("Nueva factura",e->form());add(new HorizontalLayout(new H2("Facturación"),nueva),new Paragraph("Administre las facturas emitidas por la clínica."));grid.addColumn(Factura::getNumero).setHeader("FACTURA");grid.addColumn(f->f.getPaciente().getNombreCompleto()).setHeader("PACIENTE");grid.addColumn(Factura::getFecha).setHeader("FECHA");grid.addColumn(Factura::getTotal).setHeader("TOTAL");grid.addColumn(Factura::getSaldo).setHeader("SALDO");grid.addColumn(Factura::getEstado).setHeader("ESTADO");grid.setWidthFull();add(grid);cargar();} void cargar(){grid.setItems(empresa==null?List.of():service.listar(empresa));} void form(){if(empresa==null)return;Dialog d=new Dialog();ComboBox<Paciente> paciente=new ComboBox<>("Paciente",pacientes.listarPorEmpresa(empresa));paciente.setItemLabelGenerator(Paciente::getNombreCompleto);TextField numero=new TextField("Número");BigDecimalField subtotal=new BigDecimalField("Subtotal");BigDecimalField descuento=new BigDecimalField("Descuento");BigDecimalField impuestos=new BigDecimalField("Impuestos");Button guardar=new Button("Emitir",e->{try{service.crear(empresa,paciente.getValue().getId(),numero.getValue(),subtotal.getValue(),descuento.getValue(),impuestos.getValue());d.close();cargar();Notification.show("Factura creada correctamente.");}catch(Exception x){Notification.show(x.getMessage());}});d.add(new VerticalLayout(paciente,numero,subtotal,descuento,impuestos,guardar));d.open();}}
